effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _viewport_ratio acProporcaoDoNode
vec2 u_xlat0;
bool u_xlatb0;
bvec2 u_xlatb1;
vec3 u_xlat2;
vec2 u_xlat3;
bvec2 u_xlatb6;
void main()
{
    u_xlat0.xy = acScreenNorm.xy + vec2(-0.5, -0.5);
    u_xlat0.xy = u_xlat0.xy * _viewport_ratio.xy;
    u_xlat3.xy = u_xlat0.yy * hlslcc_mtx4x4_trans_mat[1].xy;
    u_xlat0.xy = hlslcc_mtx4x4_trans_mat[0].xy * u_xlat0.xx + u_xlat3.xy;
    u_xlat0.xy = u_xlat0.xy + hlslcc_mtx4x4_trans_mat[3].xy;
    u_xlat0.xy = u_xlat0.xy / _viewport_ratio.xy;
    u_xlat0.xy = u_xlat0.xy + vec2(0.5, 0.5);
    u_xlatb6.xy = lessThan(u_xlat0.xyxy, vec4(0.0, 0.0, 0.0, 0.0)).xy;
    u_xlatb1.xy = lessThan(vec4(1.0, 1.0, 0.0, 0.0), u_xlat0.xyxx).xy;
    u_xlat2.xyz = texture(inputImg, u_xlat0.xy).xyz;
    u_xlatb0 = u_xlatb6.x || u_xlatb1.x;
    u_xlatb0 = u_xlatb6.y || u_xlatb0;
    u_xlatb0 = u_xlatb1.y || u_xlatb0;
    u_xlat0.x = (u_xlatb0) ? 0.0 : 1.0;
    fragColor.xyz = u_xlat0.xxx * u_xlat2.xyz;
    fragColor.w = u_xlat0.x * _blend_alpha;
    return;
}
